import base64
from io import BytesIO
from pptx import Presentation

# One input item: binary "data" holds the template loaded by "Load PPTX
# Template", json holds the values set by "Set Demo Values".
item = _items[0]
template_bytes = base64.b64decode(item["binary"]["data"]["data"])

# Map PowerPoint shape names -> replacement text. Open the template in
# PowerPoint (or print shape.name for each shape) to find the names for
# your own slides - these two match the sample template's title slide.
replacements = {
    "Title 1": item["json"]["title"],
    "Text Placeholder 2": item["json"]["subtitle"],
}

prs = Presentation(BytesIO(template_bytes))
slide = prs.slides[0]

for shape in slide.shapes:
    if shape.has_text_frame and shape.name in replacements:
        shape.text_frame.text = replacements[shape.name]

output = BytesIO()
prs.save(output)
output_b64 = base64.b64encode(output.getvalue()).decode("utf-8")

return [{
    "json": {"fileName": "PPT_Template_filled.pptx"},
    "binary": {
        "data": {
            "data": output_b64,
            "mimeType": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
            "fileName": "PPT_Template_filled.pptx",
            "fileExtension": "pptx",
        }
    },
}]
